import { createI18n } from '@pyreon/i18n/core'

const eur = { style: 'currency', currency: 'EUR' } as const
const mail = createI18n({
  locale: 'en',
  messages: {
    en: { receipt: 'Paid {{amount, eur}} on {{when, date}}' },
    de: { receipt: '{{amount, eur}} bezahlt am {{when, date}}' },
  },
  numberFormats: { en: { eur }, de: { eur } },
})

const when = new Date(Date.UTC(2026, 10, 11))
mail.t('receipt', { amount: 42, when })  // 'Paid €42.00 on Nov 11, 2026'
mail.locale.set('de')
mail.t('receipt', { amount: 42, when })  // '42,00 € bezahlt am 11.11.2026'
